import random
import string
from typing import List

# Generator for SAS command/script files consumed by readstat_parse_sas_commands.
# We aim to produce valid, parseable SAS commands that define an INPUT schema
# for a delimited text file, covering various variable types, formats, labels,
# missing values, and options the parser is likely to understand when building
# a readstat_schema_t.
#
# Constraints:
# - Return bytes <= 4096
# - No I/O
# - Deterministic under seed
#
# Strategy:
# - Emit a minimal, valid SAS program with options, a DATA step, INFILE, LENGTH,
#   LABEL, FORMAT, and INPUT statements; then RUN;
# - Use CSV or space-delimited variants with DSD/DELIMITER options.
# - Include a mix of numeric and character variables with differing widths,
#   formats, and labels to exercise schema building.
# - Optionally include MISSOVER/TRUNCOVER, FIRSTOBS, and OBS to vary behavior.
# - Use only ASCII so encoding is simple.


def _rand_choice(rng: random.Random, seq: List[str]):
    return seq[rng.randrange(0, len(seq))]


def _sas_ident(rng: random.Random, maxlen: int = 16) -> str:
    # SAS names: start with letter or underscore, followed by letters, digits, or underscores
    first = rng.choice(string.ascii_letters + "_")
    rest_len = rng.randint(0, max(0, maxlen - 1))
    rest = "".join(rng.choice(string.ascii_letters + string.digits + "_") for _ in range(rest_len))
    return (first + rest)[:maxlen]


def _sas_label(rng: random.Random, maxlen: int = 40) -> str:
    words = [
        "age", "income", "status", "group", "score", "region", "category",
        "weight", "height", "gender", "id", "date", "time", "flag", "note"
    ]
    parts = rng.randint(2, 6)
    s = " ".join(_rand_choice(rng, words).capitalize() for _ in range(parts))
    s = s[:maxlen]
    # Escape double quotes by doubling them (SAS label uses quotes)
    return s.replace('"', '""')


def _sas_format_for_type(rng: random.Random, is_char: bool, width: int) -> str:
    if is_char:
        # Character formats end with $.
        # Basic formats: $CHARw., $w.
        if rng.random() < 0.5:
            return f"$CHAR{width}."
        else:
            return f"${width}."
    else:
        # Numeric formats: BEST., F., COMMA., DATE., TIME.
        choice = rng.random()
        if choice < 0.3:
            w = min(max(6, width), 12)
            d = rng.randint(0, min(4, w - 1))
            return f"F{w}.{d}"
        elif choice < 0.6:
            w = rng.randint(6, 12)
            d = rng.randint(0, min(4, w - 1))
            return f"COMMA{w}.{d}"
        elif choice < 0.8:
            return "BEST12."
        else:
            # Date/time like formats; these are valid even if values may be numeric in data.
            return _rand_choice(rng, ["DATE9.", "DDMMYY10.", "TIME8.", "DATETIME20."])


def _gen_vars(rng: random.Random):
    # Decide number of variables
    nvars = rng.randint(3, 10)
    vars_meta = []
    used_names = set()
    for i in range(nvars):
        # 50/50 character vs numeric, bias to include both
        is_char = (i == 0) or (i == 1 and rng.random() < 0.5) or (rng.random() < 0.5)
        name = _sas_ident(rng, 16)
        while name.lower() in used_names:
            name = _sas_ident(rng, 16)
        used_names.add(name.lower())
        if is_char:
            width = rng.randint(5, 30)
        else:
            # width for numeric in LENGTH is bytes; SAS uses 3-8 typical; choose 4 or 8
            width = _rand_choice(rng, [3, 4, 6, 8])
        label = _sas_label(rng)
        fmt = _sas_format_for_type(rng, is_char, width)
        vars_meta.append({
            "name": name,
            "char": is_char,
            "width": width,
            "label": label,
            "format": fmt,
        })
    return vars_meta


def _emit_length(vars_meta):
    # LENGTH statement: numeric without $, character with $ width.
    num_parts = []
    char_parts = []
    for v in vars_meta:
        if v["char"]:
            char_parts.append(f"{v['name']}${v['width']}")
        else:
            num_parts.append(f"{v['name']} {v['width']}")
    parts = []
    if num_parts:
        parts.append(" ".join(num_parts))
    if char_parts:
        parts.append(" ".join(char_parts))
    if not parts:
        return ""
    return f"LENGTH {' '.join(parts)};\n"


def _emit_label(vars_meta):
    lines = ["LABEL"]
    for v in vars_meta:
        lines.append(f"  {v['name']} = \"{v['label']}\"")
    return ("\n".join(lines)) + ";\n"


def _emit_format(vars_meta):
    parts = []
    for v in vars_meta:
        parts.append(f"{v['name']} {v['format']}")
    return f"FORMAT {' '.join(parts)};\n"


def _emit_input_list(vars_meta, delimiter: str, use_informat: bool, rng: random.Random):
    # Build INPUT statement for list input with DLM/DSD or default whitespace.
    # Character vars get :$w. informat optionally to bind width for list input.
    items = []
    for v in vars_meta:
        if use_informat:
            if v["char"]:
                # Use $w. informat for character
                items.append(f"{v['name']}: ${v['width']}.")
            else:
                # Use BEST. or w.d informat
                if rng.random() < 0.5:
                    items.append(f"{v['name']}: BEST12.")
                else:
                    w = rng.randint(6, 12)
                    d = rng.randint(0, min(4, w - 1))
                    items.append(f"{v['name']}: {w}.{d}")
        else:
            # No informat, just names
            items.append(v["name"])
    return f"INPUT {' '.join(items)};\n"


def _emit_infile(rng: random.Random, delimiter_mode: str):
    # The filename here is irrelevant to schema parse; use a placeholder string.
    # Use DLM/DELIMITER with DSD to indicate CSV or a chosen delimiter.
    opts = []
    if delimiter_mode == "csv":
        opts.append("DSD")
        opts.append("DELIMITER=','")
    elif delimiter_mode == "tab":
        opts.append("DSD")
        opts.append("DELIMITER='\t'")
    elif delimiter_mode == "pipe":
        opts.append("DSD")
        opts.append("DELIMITER='|' ")
    else:
        # space-delimited with MISSOVER/TRUNCOVER
        pass
    if rng.random() < 0.5:
        opts.append("MISSOVER")
    if rng.random() < 0.3:
        opts.append("TRUNCOVER")
    if rng.random() < 0.4:
        firstobs = rng.randint(1, 3)
        opts.append(f"FIRSTOBS={firstobs}")
    if rng.random() < 0.3:
        obs = rng.randint(5, 50)
        opts.append(f"OBS={obs}")
    opt_str = (" ".join(opts)).strip()
    if opt_str:
        return f"INFILE '\nDUMMY_DATA.csv' {opt_str};\n"
    else:
        return "INFILE '\nDUMMY_DATA.csv';\n"


def _emit_options(rng: random.Random):
    opts = []
    if rng.random() < 0.5:
        opts.append("OPTIONS NOCENTER;")
    if rng.random() < 0.4:
        opts.append("OPTIONS VALIDVARNAME=V7;")
    if rng.random() < 0.3:
        opts.append("OPTIONS YEARCUTOFF=1920;")
    return "\n".join(opts) + ("\n" if opts else "")


def _emit_sas_program(rng: random.Random) -> str:
    delimiter_mode = _rand_choice(rng, ["csv", "tab", "pipe", "space"])  # variety
    vars_meta = _gen_vars(rng)

    # Build program
    parts = []
    parts.append(_emit_options(rng))

    data_name = _sas_ident(rng, 16)
    parts.append(f"DATA {data_name};\n")
    parts.append(_emit_infile(rng, delimiter_mode))

    # LENGTH defines storage/widths for character and numeric
    parts.append(_emit_length(vars_meta))

    # LABEL and FORMAT
    if rng.random() < 0.9:
        parts.append(_emit_label(vars_meta))
    if rng.random() < 0.9:
        parts.append(_emit_format(vars_meta))

    # INPUT statement: use informats about half the time
    use_informat = rng.random() < 0.7
    parts.append(_emit_input_list(vars_meta, delimiter_mode, use_informat, rng))

    # Optional: INFORMAT statement mirroring formats for character parsing
    if rng.random() < 0.4:
        inf_parts = []
        for v in vars_meta:
            if v["char"]:
                inf_parts.append(f"{v['name']} ${v['width']}.")
            else:
                inf_parts.append(f"{v['name']} BEST12.")
        parts.append(f"INFORMAT {' '.join(inf_parts)};\n")

    parts.append("RUN;\n")

    program = "".join(parts)
    # Ensure within size limit
    return program[:4000]


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    program = _emit_sas_program(rng)
    return program.encode("ascii", errors="ignore")

import random
import string
from typing import List

def _rand_choice(rng, seq):
    return seq[rng.randrange(0, len(seq))]

def _quoted(s: str) -> str:
    # Quote with single quotes and escape embedded quotes by doubling per SPSS convention
    return "'" + s.replace("'", "''") + "'"

def _random_var_name(rng: random.Random, idx: int) -> str:
    # SPSS variable naming: start with letter or @, $, #; keep simple: start with letter
    # Max length typically 64 (depending on version). We'll keep <= 8 for compatibility.
    letters = string.ascii_uppercase
    rest = string.ascii_uppercase + string.digits + "_"
    name = rng.choice(letters)
    length = rng.randint(1, 8)
    while len(name) < length:
        name += rng.choice(rest)
    # Ensure not purely numeric, not reserved simple words
    if name in {"ALL","BY","AND","OR","NOT"}:
        name += rng.choice("XYZ")
    return name

def _random_label(rng: random.Random, max_len: int = 40) -> str:
    words = ["age","income","score","status","group","city","state","country","index","value","cat","dog","ZETA","ALPHA","beta"]
    s = " ".join(rng.choice(words) for _ in range(rng.randint(1, 5)))
    s = s[:max_len]
    return s

def _random_formats(rng: random.Random, var_type: str) -> str:
    # Return a valid SPSS format like F8.2, A10, DATE11, COMMA8.0, DOLLAR8.2
    if var_type == 'A':
        w = rng.randint(1, 20)
        return f"A{w}"
    else:
        choices = []
        # Simple numeric
        w = rng.randint(3, 10)
        d = rng.randint(0, min(3, w-1))
        choices.append(f"F{w}.{d}")
        # Comma with decimals
        w2 = rng.randint(4, 12)
        d2 = rng.randint(0, min(3, w2-1))
        choices.append(f"COMMA{w2}.{d2}")
        # Dollar
        w3 = rng.randint(4, 12)
        d3 = rng.randint(0, min(2, w3-1))
        choices.append(f"DOLLAR{w3}.{d3}")
        # Date-like
        choices.append("DATE11")
        return rng.choice(choices)

def _make_data_list_fixed(rng: random.Random, var_specs: List[dict]) -> str:
    # Create a FIXED format DATA LIST with column ranges
    # Example: DATA LIST FIXED / v1 1-3 v2 4-13 (A) v3 14-16.
    pos = 1
    parts = []
    for spec in var_specs:
        name = spec['name']
        vtype = spec['type']  # 'N' or 'A'
        width = spec['width']
        start = pos
        end = pos + width - 1
        if vtype == 'A':
            parts.append(f"{name} {start}-{end} (A)")
        else:
            parts.append(f"{name} {start}-{end}")
        pos = end + 1
    return "DATA LIST FIXED / " + " ".join(parts) + ".\n"

def _make_data_list_list(rng: random.Random, var_specs: List[dict]) -> str:
    # Create a LIST format DATA LIST with parentheses format after names where needed
    # Example: DATA LIST LIST / v1 v2 (A10) v3.
    items = []
    for spec in var_specs:
        name = spec['name']
        vtype = spec['type']
        width = spec['width']
        if vtype == 'A':
            items.append(f"{name} (A{width})")
        else:
            # sometimes specify F format to be explicit
            if rng.random() < 0.5:
                w = max(1, min(10, width))
                d = rng.randint(0, min(2, max(0, w-1)))
                items.append(f"{name} (F{w}.{d})")
            else:
                items.append(name)
    return "DATA LIST LIST / " + " ".join(items) + ".\n"

def _make_variable_labels(rng: random.Random, var_specs: List[dict]) -> str:
    # VARIABLE LABELS v1 'label' v2 'label'.
    parts = []
    chosen = rng.sample(var_specs, k=rng.randint(1, max(1, len(var_specs))))
    for spec in chosen:
        parts.append(f"{spec['name']} {_quoted(_random_label(rng))}")
    return "VARIABLE LABELS " + " ".join(parts) + ".\n"

def _make_value_labels(rng: random.Random, var_specs: List[dict]) -> str:
    # VALUE LABELS varlist value 'label' ... . Provide for a subset of variables.
    # Numeric and short string values supported
    out = []
    candidates = [s for s in var_specs if rng.random() < 0.6]
    if not candidates:
        candidates = [rng.choice(var_specs)]
    for spec in candidates:
        entries = []
        n_entries = rng.randint(2, 5)
        if spec['type'] == 'N':
            used = set()
            for _ in range(n_entries):
                val = rng.randint(0, 9)
                if val in used:
                    val = (val + rng.randint(1, 9)) % 10
                used.add(val)
                entries.append(f"{val} {_quoted(_random_label(rng, 20))}")
        else:
            for _ in range(n_entries):
                sv = ''.join(rng.choice(string.ascii_uppercase[:8]) for _ in range(min(5, spec['width'])))
                entries.append(f"{_quoted(sv)} {_quoted(_random_label(rng, 20))}")
        out.append("VALUE LABELS " + spec['name'] + " " + " ".join(entries) + ".\n")
    return "".join(out)

def _make_missing_values(rng: random.Random, var_specs: List[dict]) -> str:
    # MISSING VALUES varlist (values...). Use either exacts or ranges
    out = []
    # Choose a couple variables
    chosen = [s for s in var_specs if rng.random() < 0.5]
    if not chosen:
        return ""
    for spec in chosen:
        if spec['type'] == 'N':
            if rng.random() < 0.5:
                lo = rng.randint(-9, -1)
                hi = rng.randint(lo, -1)
                out.append(f"MISSING VALUES {spec['name']} ({lo} THRU {hi}).\n")
            else:
                vals = sorted(set(rng.randint(-3, 3) for _ in range(rng.randint(1, 3))))
                inside = " ".join(str(v) for v in vals)
                out.append(f"MISSING VALUES {spec['name']} ({inside}).\n")
        else:
            # strings: exact values
            k = rng.randint(1, 3)
            vals = []
            for _ in range(k):
                sv = ''.join(rng.choice(string.ascii_uppercase) for _ in range(min(3, spec['width'])))
                vals.append(_quoted(sv))
            out.append(f"MISSING VALUES {spec['name']} (" + " ".join(vals) + ").\n")
    return "".join(out)

def _make_formats(rng: random.Random, var_specs: List[dict]) -> str:
    # FORMATS v1 (F8.2) v2 (A10) ... . Randomly include subset
    parts = []
    chosen = rng.sample(var_specs, k=rng.randint(1, max(1, len(var_specs))))
    for spec in chosen:
        fmt = _random_formats(rng, 'A' if spec['type']=='A' else 'N')
        parts.append(f"{spec['name']} ({fmt})")
    return "FORMATS " + " ".join(parts) + ".\n"

def _make_var_level_metadata(rng: random.Random, var_specs: List[dict]) -> str:
    out = []
    if rng.random() < 0.8:
        out.append(_make_variable_labels(rng, var_specs))
    if rng.random() < 0.7:
        out.append(_make_formats(rng, var_specs))
    if rng.random() < 0.6:
        out.append(_make_value_labels(rng, var_specs))
    if rng.random() < 0.5:
        out.append(_make_missing_values(rng, var_specs))
    return "".join(out)

def _make_file_level_metadata(rng: random.Random) -> str:
    out = []
    if rng.random() < 0.7:
        label = _random_label(rng, 60)
        out.append("FILE LABEL " + _quoted(label) + ".\n")
    if rng.random() < 0.5:
        title = _random_label(rng, 50)
        out.append("TITLE " + _quoted(title) + ".\n")
    return "".join(out)

def _make_execute(rng: random.Random) -> str:
    # EXECUTE is optional; include to trigger certain parser flows
    return "EXECUTE.\n"

def _make_dataset_name(rng: random.Random) -> str:
    # SET or DATASET NAME can appear; include a DATASET NAME for variety
    ds = ''.join(rng.choice(string.ascii_uppercase) for _ in range(rng.randint(3, 8)))
    return f"DATASET NAME {ds}.\n"

def _build_var_specs(rng: random.Random) -> List[dict]:
    n = rng.randint(3, 8)
    specs = []
    used_names = set()
    for i in range(n):
        name = _random_var_name(rng, i)
        while name in used_names:
            name = _random_var_name(rng, i)
        used_names.add(name)
        vtype = 'A' if rng.random() < 0.4 else 'N'
        if vtype == 'A':
            width = rng.randint(3, 20)
        else:
            # choose storage width footprint in fixed layout; not an SPSS requirement but for column ranges
            width = rng.randint(2, 6)
        specs.append({"name": name, "type": vtype, "width": width})
    return specs

def _maybe_with_comments(rng: random.Random, s: str) -> str:
    if rng.random() < 0.5:
        lines = s.splitlines(True)
        # Prepend and intersperse comment-style lines (SPSS ignores lines starting with * until period)
        # We'll add "* comment." full-line comments.
        comments = ["* " + _random_label(rng, 50) + ".\n" for _ in range(rng.randint(1, 3))]
        insert_at = rng.randrange(0, len(lines)+1)
        return "".join(lines[:insert_at] + comments + lines[insert_at:])
    return s

def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    var_specs = _build_var_specs(rng)

    # Choose DATA LIST style
    if rng.random() < 0.5:
        data_list = _make_data_list_fixed(rng, var_specs)
    else:
        data_list = _make_data_list_list(rng, var_specs)

    pieces = []
    # Optional file-level metadata first
    pieces.append(_make_file_level_metadata(rng))
    pieces.append(_make_dataset_name(rng))
    pieces.append(data_list)
    pieces.append(_make_var_level_metadata(rng, var_specs))
    # Optionally add additional syntactic constructs that are generally harmless
    if rng.random() < 0.4:
        pieces.append("CACHE.\n")
    if rng.random() < 0.6:
        pieces.append(_make_execute(rng))

    script = "".join(pieces)
    script = _maybe_with_comments(rng, script)

    # Ensure size limit
    if len(script) > 4096:
        script = script[:4090] + "\n.\n"

    return script.encode('utf-8')

import random
import io
import datetime

# Generator for a delimited/plain-text data file that pairs with a ReadStat text schema.
# The fuzzer stub calls FUZZ_PARAM_FILENAME() to obtain a filename containing bytes this
# function returns. We therefore emit a plausible CSV/TSV or fixed-width text file content
# that exercises a wide range of value types, missingness markers, quoted fields, escaped
# delimiters, multi-line notes, and locale-decimal variants, while remaining valid text.
#
# Constraints:
# - Keep total size <= 4096 bytes.
# - Be seeded-random to vary structure while staying valid.
# - Avoid malformed encodings; stick to UTF-8 ASCII subset plus a few UTF-8 characters.
# - Include header sometimes; include different delimiters and quote usages.
# - Include fields that look like numbers, dates, strings, tagged-missing-like, etc.

DELIMS = [',', '\t', ';', '|']
NEWLINES = ['\n', '\r\n']
DECIMAL_SEPARATORS = ['.', ',']
QUOTE_CHARS = ['"', "'"]

UTF8_WORDS = [
    'alpha', 'bravo', 'charlie', 'delta', 'echo', 'foxtrot',
    'naïve', 'café', 'ümlaut', 'π', '数据', 'данные', 'dados'
]

MISSING_MARKERS = [
    '', 'NA', 'NaN', 'null', 'NULL', '.', '.a', '.b', 'N/A'
]

DATE_SAMPLES = [
    '2020-01-01', '1999-12-31', '2001-02-03', '1970-01-01', '2038-01-19'
]
TIME_SAMPLES = [
    '00:00:00', '12:34:56', '23:59:59'
]
DATETIME_SAMPLES = [
    '2020-01-01 12:00:00', '1999-12-31 23:59:59', '1970-01-01 00:00:00'
]

BOOL_SAMPLES = ['0', '1', 'true', 'false', 'TRUE', 'FALSE', 'T', 'F']

INT_SAMPLES = [
    '-2147483648', '-32768', '-128', '0', '1', '42', '127', '255', '32767', '2147483647'
]

FLOAT_SAMPLES = [
    '-1.0', '0.0', '3.14159', '2.71828', '1e3', '-2.5e-4', '6.022e23'
]

STRING_MARKERS = [
    'hello', 'world', 'a,b', 'quoted "quote"', 'with,comma', 'with;semi', 'with|pipe',
    'tabs\there', ' spaced ', '"startsquote', "endsquote'", 'line\nbreak'
]

def _rand_choice(rng, seq):
    return seq[rng.randrange(0, len(seq))]

def _quoted(rng, s, quote_char):
    # Double the quote char inside the field when needed (CSV-style), or backslash-escape sometimes
    if quote_char in s and rng.random() < 0.7:
        s = s.replace(quote_char, quote_char + quote_char)
    if rng.random() < 0.15:
        # sprinkle a delimiter inside to test quoted handling
        s += _rand_choice(rng, [',', ';', '|'])
    return f"{quote_char}{s}{quote_char}"

def _maybe_quote(rng, s, delim, quote_char):
    needs_quote = any(x in s for x in [delim, '\n', '\r']) or s.strip() != s or quote_char in s
    if rng.random() < 0.3:
        needs_quote = True
    return _quoted(rng, s, quote_char) if needs_quote else s

def _decimalize(rng, num_str, dec_char):
    if dec_char == '.':
        return num_str
    # Replace decimal dot with comma when appropriate
    if '.' in num_str:
        return num_str.replace('.', ',')
    # For scientific notation, swap dot if present
    if 'e' in num_str or 'E' in num_str:
        parts = num_str.split('e') if 'e' in num_str else num_str.split('E')
        mant = parts[0]
        expsep = 'e' if 'e' in num_str else 'E'
        if '.' in mant:
            mant = mant.replace('.', ',')
        return mant + expsep + parts[1]
    return num_str

def _gen_row(rng, col_specs, delim, quote_char, dec_char):
    fields = []
    for kind in col_specs:
        if kind == 'int':
            v = _rand_choice(rng, INT_SAMPLES)
        elif kind == 'float':
            v = _decimalize(rng, _rand_choice(rng, FLOAT_SAMPLES), dec_char)
        elif kind == 'bool':
            v = _rand_choice(rng, BOOL_SAMPLES)
        elif kind == 'date':
            v = _rand_choice(rng, DATE_SAMPLES)
        elif kind == 'time':
            v = _rand_choice(rng, TIME_SAMPLES)
        elif kind == 'datetime':
            v = _rand_choice(rng, DATETIME_SAMPLES)
        elif kind == 'string':
            base = _rand_choice(rng, UTF8_WORDS + STRING_MARKERS)
            if rng.random() < 0.2:
                base = base + str(rng.randrange(0, 100))
            v = base
        elif kind == 'missing':
            v = _rand_choice(rng, MISSING_MARKERS)
        else:
            v = ''
        # Occasionally inject empty to test missing handling
        if rng.random() < 0.05:
            v = ''
        vq = _maybe_quote(rng, v, delim, quote_char)
        fields.append(vq)
    return delim.join(fields)

def _gen_fixed_width_row(rng, col_specs, widths, dec_char):
    chunks = []
    for kind, w in zip(col_specs, widths):
        if kind == 'int':
            v = _rand_choice(rng, INT_SAMPLES)
        elif kind == 'float':
            v = _decimalize(rng, _rand_choice(rng, FLOAT_SAMPLES), dec_char)
        elif kind == 'bool':
            v = _rand_choice(rng, BOOL_SAMPLES)
        elif kind == 'date':
            v = _rand_choice(rng, DATE_SAMPLES)
        elif kind == 'time':
            v = _rand_choice(rng, TIME_SAMPLES)
        elif kind == 'datetime':
            v = _rand_choice(rng, DATETIME_SAMPLES)
        elif kind == 'string':
            v = _rand_choice(rng, UTF8_WORDS + STRING_MARKERS)
        elif kind == 'missing':
            v = _rand_choice(rng, MISSING_MARKERS)
        else:
            v = ''
        if rng.random() < 0.05:
            v = ''
        # Fit to width: left for strings, right for numbers
        s = v
        if len(s) > w:
            s = s[:w]
        pad_char = ' '
        if kind in ('int', 'float', 'bool') and rng.random() < 0.5:
            s = s.rjust(w, pad_char)
        else:
            s = s.ljust(w, pad_char)
        chunks.append(s)
    return ''.join(chunks)

def _build_delimited(rng):
    delim = _rand_choice(rng, DELIMS)
    quote_char = _rand_choice(rng, QUOTE_CHARS)
    nl = _rand_choice(rng, NEWLINES)
    dec_char = _rand_choice(rng, DECIMAL_SEPARATORS)

    # Column spec tries to cover numeric/string/missing/time classes
    base_specs = ['int', 'float', 'string', 'missing', 'bool', 'date', 'time', 'datetime']
    rng.shuffle(base_specs)
    col_count = rng.randint(4, min(10, len(base_specs)))
    col_specs = base_specs[:col_count]

    # Maybe duplicate one type to vary distributions
    while len(col_specs) < col_count:
        col_specs.append(_rand_choice(rng, base_specs))

    out = io.StringIO()

    # Optional header
    if rng.random() < 0.8:
        headers = []
        for i, k in enumerate(col_specs):
            name = {
                'int': 'id', 'float': 'value', 'string': 'name', 'missing': 'opt',
                'bool': 'flag', 'date': 'date', 'time': 'time', 'datetime': 'when'
            }.get(k, f'col{i}')
            # Ensure uniqueness
            headers.append(f"{name}{i}")
        header_line = delim.join(headers)
        out.write(header_line + nl)

    # Row count
    rows = rng.randint(5, 40)

    # Occasionally emit a comment/preamble line (some schemas support comments)
    if rng.random() < 0.3:
        out.write(f"# generated {datetime.date.today().isoformat()}" + nl)

    for _ in range(rows):
        row = _gen_row(rng, col_specs, delim, quote_char, dec_char)
        out.write(row + nl)

    # Trailing newline ensured; maybe an extra blank line
    if rng.random() < 0.2:
        out.write(nl)

    return out.getvalue()

def _build_fixed_width(rng):
    nl = _rand_choice(rng, NEWLINES)
    dec_char = _rand_choice(rng, DECIMAL_SEPARATORS)
    # Choose widths that are reasonable; include some narrow columns to test truncation
    widths = [rng.randint(2, 6), rng.randint(3, 8), rng.randint(4, 12), rng.randint(2, 10), rng.randint(2, 8)]
    kinds_pool = ['int', 'float', 'string', 'missing', 'bool', 'date', 'time']
    col_specs = [ _rand_choice(rng, kinds_pool) for _ in widths ]

    out = io.StringIO()

    # No header in typical fixed-width, but sometimes an initial ruler line helps parsers ignore
    if rng.random() < 0.2:
        out.write(''.join(str((i % 10)) for i in range(sum(widths))) + nl)

    rows = rng.randint(5, 50)
    for _ in range(rows):
        out.write(_gen_fixed_width_row(rng, col_specs, widths, dec_char) + nl)

    return out.getvalue()

def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Choose format: prefer delimited (more schemas target CSV/TSV), but sometimes fixed-width
    if rng.random() < 0.75:
        text = _build_delimited(rng)
    else:
        text = _build_fixed_width(rng)

    data = text.encode('utf-8')
    # Ensure under size limit; if oversized, trim from the end at a newline boundary if possible
    if len(data) > 4096:
        # Find last newline before limit
        cut = data.rfind(b"\n", 0, 4096)
        if cut == -1:
            data = data[:4096]
        else:
            data = data[:cut+1]
    return data
